    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 ethAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ethAmount)); require(ethAmount <= 1000000000000000000000000000000);
        require(ethAmount <= address(this).balance, "insufficient test balance");
        require(ethAmount > 0, "amount must be positive");

        uint256 balanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 totalRemainingBefore = c.totalRemaining(); if (__ESBMC_reverted()) return;
        uint256 valueBefore = c.value(); if (__ESBMC_reverted()) return;
        uint256 expectedAmount = valueBefore;
        if (expectedAmount > totalRemainingBefore) {
            expectedAmount = totalRemainingBefore;
        }

        bool reverted = false;
        c.getTokens{value: ethAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            // successful call
        }

        uint256 balanceAfter = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        bool blacklistedAfter = c.blacklist(address(this)); if (__ESBMC_reverted()) return;

        assert(
            reverted ||
            (expectedAmount > 0 &&
             balanceAfter == balanceBefore + expectedAmount &&
             blacklistedAfter)
        );
    }

    receive() external payable {}
}

